import{_ as e,C as t,c as o,o as a,j as i,G as r,a0 as n,b as s,a as l,w as h,a1 as u}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Workshop: Advanced Mental Game Session (3-4 Hours)","description":"","frontmatter":{},"headers":[],"relativePath":"en/workshop.md","filePath":"en/workshop.md"}');const d=e({name:"en/workshop.md"},[["render",function(e,c,d,p,g,m){const f=t("AdBanner"),b=t("Mermaid"),q=t("AdInArticle");return a(),o("div",null,[c[4]||(c[4]=i("h1",{id:"workshop-advanced-mental-game-session-3-4-hours",tabindex:"-1"},[l("Workshop: Advanced Mental Game Session (3-4 Hours) "),i("a",{class:"header-anchor",href:"#workshop-advanced-mental-game-session-3-4-hours","aria-label":'Permalink to "Workshop: Advanced Mental Game Session (3-4 Hours)"'},"​")],-1)),r(f),c[5]||(c[5]=n('<h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This workshop is an advanced 3-4 hour theoretical session for 6-8 elite players, focusing on deep psychological work and vulnerability-based learning. It goes beyond basic mental skills to explore the inner game at a profound level.</p><div class="tip custom-block"><p class="custom-block-title">Two Sections in This Guide</p><ul><li><strong><a href="#for-participants">For Participants</a></strong> - What players will experience and learn</li><li><strong><a href="#for-facilitators">For Facilitators</a></strong> - How to conduct the workshop as a Mental Performance Coordinator</li></ul></div><p><strong>Difference from Beginner Session:</strong></p><ul><li><strong>Beginner (2-3h):</strong> Introduction to mental game concepts → <a href="/en/mental-journey/session-guide">See Mental Journey Guide</a></li><li><strong>Advanced (3-4h):</strong> Deep psychological work with vulnerability exercises (this page)</li></ul><h2 id="quick-access" tabindex="-1">Quick Access <a class="header-anchor" href="#quick-access" aria-label="Permalink to &quot;Quick Access&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Purpose</th><th>Access</th></tr></thead><tbody><tr><td><strong>For Participants</strong></td><td>What to expect and how to prepare</td><td><a href="#for-participants">View Section</a></td></tr><tr><td><strong>For Facilitators</strong></td><td>Complete session guide and exercises</td><td><a href="#for-facilitators">View Section</a></td></tr><tr><td><strong>Session Materials</strong></td><td>Exercises and worksheets</td><td><a href="#facilitator-materials">View Materials</a></td></tr><tr><td><strong>Related Guides</strong></td><td>Other training formats</td><td><a href="/en/mental-journey/">Mental Journey</a> • <a href="/en/training-camp">Training Camp</a></td></tr></tbody></table><hr><h2 id="for-participants" tabindex="-1">For Participants <a class="header-anchor" href="#for-participants" aria-label="Permalink to &quot;For Participants&quot;">​</a></h2><h3 id="what-to-expect" tabindex="-1">What to Expect <a class="header-anchor" href="#what-to-expect" aria-label="Permalink to &quot;What to Expect&quot;">​</a></h3><p>This is not a typical training session. You&#39;ll engage in deep discussions about the mental and emotional aspects of pétanque that rarely get talked about openly.</p><p><strong>This Workshop Is:</strong></p><ul><li>✅ A safe space to explore inner thoughts and fears</li><li>✅ Vulnerability-based learning with teammates</li><li>✅ Connecting mental patterns to performance</li><li>✅ Building team psychological intelligence</li></ul><p><strong>This Workshop Is NOT:</strong></p><ul><li>❌ Technical coaching or tactics training</li><li>❌ Therapy or counseling</li><li>❌ Positive thinking or motivation speeches</li><li>❌ Judgment or criticism</li></ul><h3 id="session-structure" tabindex="-1">Session Structure <a class="header-anchor" href="#session-structure" aria-label="Permalink to &quot;Session Structure&quot;">​</a></h3>',16)),(a(),s(u,null,{default:h(()=>[r(b,{id:"mermaid-167",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BWorkshop%20Session%5D%20--%3E%20B%5BFoundation%2060min%5D%0A%20%20%20%20B%20--%3E%20C%5BDeep%20Work%2090min%5D%0A%20%20%20%20C%20--%3E%20D%5BIntegration%2045min%5D%0A%20%20%20%20D%20--%3E%20E%5BClosing%2015min%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23ffe4e1%0A%20%20%20%20style%20D%20fill%3A%23e3f2fd%0A%20%20%20%20style%20E%20fill%3A%23f3e5f5%0A"})]),fallback:h(()=>[...c[0]||(c[0]=[l(" Loading... ",-1)])]),_:1})),c[6]||(c[6]=n('<p><strong>Total Duration:</strong> 3-4 hours <strong>Group Size:</strong> 6-8 players <strong>Format:</strong> Circle discussion with structured exercises</p><h3 id="what-you-ll-learn" tabindex="-1">What You&#39;ll Learn <a class="header-anchor" href="#what-you-ll-learn" aria-label="Permalink to &quot;What You&#39;ll Learn&quot;">​</a></h3><h4 id="phase-1-foundation-60-min" tabindex="-1">Phase 1: Foundation (60 min) <a class="header-anchor" href="#phase-1-foundation-60-min" aria-label="Permalink to &quot;Phase 1: Foundation (60 min)&quot;">​</a></h4><ul><li>Ground rules for psychological safety</li><li>The &quot;Check-In Matrix&quot; - acknowledging your current state</li><li>The &quot;Iceberg of Pétanque&quot; - exploring hidden thoughts</li></ul><h4 id="phase-2-deep-work-90-min" tabindex="-1">Phase 2: Deep Work (90 min) <a class="header-anchor" href="#phase-2-deep-work-90-min" aria-label="Permalink to &quot;Phase 2: Deep Work (90 min)&quot;">​</a></h4><ul><li>Creating your &quot;User Manual&quot; for teammates</li><li>Connecting mental patterns to performance</li><li>&quot;Fear in a Hat&quot; - breaking isolation through shared vulnerability</li></ul><h4 id="phase-3-integration-45-min" tabindex="-1">Phase 3: Integration (45 min) <a class="header-anchor" href="#phase-3-integration-45-min" aria-label="Permalink to &quot;Phase 3: Integration (45 min)&quot;">​</a></h4><ul><li>Reframing your Inner Critic to Inner Coach</li><li>Creating team protocols for competition</li><li>Actionable takeaways for the piste</li></ul><h4 id="phase-4-closing-15-min" tabindex="-1">Phase 4: Closing (15 min) <a class="header-anchor" href="#phase-4-closing-15-min" aria-label="Permalink to &quot;Phase 4: Closing (15 min)&quot;">​</a></h4><ul><li>Reflection and commitment</li><li>Follow-up support</li></ul><h3 id="ground-rules" tabindex="-1">Ground Rules <a class="header-anchor" href="#ground-rules" aria-label="Permalink to &quot;Ground Rules&quot;">​</a></h3><p>Before the session begins, all participants agree to:</p><div class="tip custom-block"><p class="custom-block-title">The Container - Essential Ground Rules</p><ol><li><strong>Confidentiality</strong> - What&#39;s said here, stays here</li><li><strong>The Vegas Rule</strong> - Lessons leave the room, stories stay</li><li><strong>No Fixing</strong> - Witness and understand, don&#39;t try to solve</li><li><strong>Right to Pass</strong> - Vulnerability cannot be coerced</li><li><strong>Respect the Process</strong> - Trust the discomfort</li></ol></div><h3 id="what-to-bring" tabindex="-1">What to Bring <a class="header-anchor" href="#what-to-bring" aria-label="Permalink to &quot;What to Bring&quot;">​</a></h3><p><strong>Required:</strong></p><ul><li>Open mind and willingness to share</li><li>Your own experiences and challenges</li><li>Respect for others&#39; vulnerability</li></ul><p><strong>Optional:</strong></p><ul><li>Notebook for personal reflections</li><li>Questions about specific mental challenges</li></ul><h3 id="key-activities-you-ll-experience" tabindex="-1">Key Activities You&#39;ll Experience <a class="header-anchor" href="#key-activities-you-ll-experience" aria-label="Permalink to &quot;Key Activities You&#39;ll Experience&quot;">​</a></h3><h4 id="the-check-in-matrix" tabindex="-1">The Check-In Matrix <a class="header-anchor" href="#the-check-in-matrix" aria-label="Permalink to &quot;The Check-In Matrix&quot;">​</a></h4><p>Place yourself on a grid of energy and mood. Normalize that we all have different states.</p><h4 id="the-iceberg-of-petanque" tabindex="-1">The Iceberg of Pétanque <a class="header-anchor" href="#the-iceberg-of-petanque" aria-label="Permalink to &quot;The Iceberg of Pétanque&quot;">​</a></h4><p>Explore what&#39;s happening below the surface - the thoughts and fears nobody sees.</p><h4 id="the-user-manual" tabindex="-1">The User Manual <a class="header-anchor" href="#the-user-manual" aria-label="Permalink to &quot;The User Manual&quot;">​</a></h4><p>Create an operating manual for yourself so teammates understand how to support you.</p><h4 id="fear-in-a-hat" tabindex="-1">Fear in a Hat <a class="header-anchor" href="#fear-in-a-hat" aria-label="Permalink to &quot;Fear in a Hat&quot;">​</a></h4><p>Anonymously share deep fears and hear them validated by peers. Break the isolation.</p><h4 id="inner-critic-reframing" tabindex="-1">Inner Critic Reframing <a class="header-anchor" href="#inner-critic-reframing" aria-label="Permalink to &quot;Inner Critic Reframing&quot;">​</a></h4><p>Transform harsh self-talk into supportive coaching language.</p><h3 id="after-the-workshop" tabindex="-1">After the Workshop <a class="header-anchor" href="#after-the-workshop" aria-label="Permalink to &quot;After the Workshop&quot;">​</a></h3><p>You&#39;ll leave with:</p><ul><li>Deeper understanding of your mental patterns</li><li>Team protocols for supporting each other</li><li>Reframed Inner Coach phrases</li><li>Connection to teammates through shared vulnerability</li><li>Actionable tools for competition</li></ul><div class="warning custom-block"><p class="custom-block-title">Vulnerability Hangover</p><p>After deep sharing, you might feel exposed or regretful. This is normal. The facilitator will check in with you within 24 hours. Remember: what you shared helped everyone.</p></div>',33)),r(q),c[7]||(c[7]=n('<hr><h2 id="for-facilitators" tabindex="-1">For Facilitators <a class="header-anchor" href="#for-facilitators" aria-label="Permalink to &quot;For Facilitators&quot;">​</a></h2><h3 id="your-role-as-mental-performance-coordinator" tabindex="-1">Your Role as Mental Performance Coordinator <a class="header-anchor" href="#your-role-as-mental-performance-coordinator" aria-label="Permalink to &quot;Your Role as Mental Performance Coordinator&quot;">​</a></h3><p>As the <strong>Mental Performance Coordinator (MPC)</strong>, you facilitate deep discussions about the mental game, creating psychological safety that translates to performance on the piste.</p><div class="warning custom-block"><p class="custom-block-title">Critical Concept</p><p><strong>You are not a technical coach or therapist.</strong> Your role is to facilitate vulnerability-based learning that helps players understand the connection between their inner thoughts and their performance.</p></div><h3 id="your-responsibilities" tabindex="-1">Your Responsibilities <a class="header-anchor" href="#your-responsibilities" aria-label="Permalink to &quot;Your Responsibilities&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Key Responsibilities</p><ul><li><strong>Facilitate, don&#39;t lecture</strong> - You guide discussion, not teach technique</li><li><strong>Hold the space</strong> - Create and maintain psychological safety</li><li><strong>Bridge theory to practice</strong> - Connect website content to inner experience</li><li><strong>Monitor group dynamics</strong> - Notice who&#39;s engaged, who&#39;s resistant</li><li><strong>Maintain boundaries</strong> - Know when to refer to professional help</li></ul></div><h3 id="pre-workshop-preparation" tabindex="-1">Pre-Workshop Preparation <a class="header-anchor" href="#pre-workshop-preparation" aria-label="Permalink to &quot;Pre-Workshop Preparation&quot;">​</a></h3><h3 id="essential-competencies" tabindex="-1">Essential Competencies <a class="header-anchor" href="#essential-competencies" aria-label="Permalink to &quot;Essential Competencies&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Competency</th><th>What It Means</th><th>How to Develop</th></tr></thead><tbody><tr><td><strong>Emotional Intelligence</strong></td><td>Detect micro-expressions of discomfort</td><td>Practice active observation</td></tr><tr><td><strong>Neutral Authority</strong></td><td>Command respect without technical power</td><td>Establish credibility through presence</td></tr><tr><td><strong>Sport Context</strong></td><td>Understand pressure mechanics</td><td>Learn pétanque terminology and culture</td></tr><tr><td><strong>Verbal Aikido</strong></td><td>Align with resistance, don&#39;t fight it</td><td>Practice non-defensive communication</td></tr></tbody></table><details class="details custom-block"><summary>Key Pétanque Terms to Know</summary><ul><li><strong>Carreau</strong> - Perfect shot that displaces opponent&#39;s boule</li><li><strong>Bibber</strong> - The &quot;yips&quot; - involuntary tremor during release</li><li><strong>Donnée</strong> - The &quot;given&quot; - accepting the terrain as it is</li><li><strong>Portée</strong> - Throwing without bounce</li><li><strong>Roulette</strong> - Rolling shot</li><li><strong>Cochonnet</strong> - The target ball (jack)</li></ul></details><h2 id="physical-setup-the-magic-circle" tabindex="-1">Physical Setup: The Magic Circle <a class="header-anchor" href="#physical-setup-the-magic-circle" aria-label="Permalink to &quot;Physical Setup: The Magic Circle&quot;">​</a></h2><h3 id="location-requirements" tabindex="-1">Location Requirements <a class="header-anchor" href="#location-requirements" aria-label="Permalink to &quot;Location Requirements&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Critical Setup</p><p><strong>Choose a neutral space AWAY from the piste.</strong> This signals a shift from physical to mental work.</p><p>Requirements:</p><ul><li>✅ Soundproof or private</li><li>✅ Comfortable temperature</li><li>✅ No distractions (phones off)</li><li>✅ Natural light if possible</li><li>✅ Separate from training area</li></ul></div><h3 id="the-circle-configuration" tabindex="-1">The Circle Configuration <a class="header-anchor" href="#the-circle-configuration" aria-label="Permalink to &quot;The Circle Configuration&quot;">​</a></h3><p><strong>Seating:</strong></p><ul><li>Perfect circle of chairs</li><li><strong>NO TABLES</strong> - Tables create barriers and hide body language</li><li>All chairs at same height (no power positions)</li><li>Coordinator sits as part of circle (not at front)</li></ul><p><strong>Center Artifacts:</strong></p><ul><li>Place boules and cochonnet in center</li><li>Anchors the work to the sport</li><li>Visual reminder of shared purpose</li></ul>',19)),(a(),s(u,null,{default:h(()=>[r(b,{id:"mermaid-632",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BPhysical%20Space%5D%20--%3E%20B%5BSignals%20Mental%20Shift%5D%0A%20%20%20%20A%20--%3E%20C%5BNo%20Barriers%5D%0A%20%20%20%20A%20--%3E%20D%5BEqual%20Positioning%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BPsychological%20Safety%5D%0A%20%20%20%20C%20--%3E%20E%0A%20%20%20%20D%20--%3E%20E%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:h(()=>[...c[1]||(c[1]=[l(" Loading... ",-1)])]),_:1})),c[8]||(c[8]=n('<h2 id="session-structure-3-4-hours" tabindex="-1">Session Structure (3-4 Hours) <a class="header-anchor" href="#session-structure-3-4-hours" aria-label="Permalink to &quot;Session Structure (3-4 Hours)&quot;">​</a></h2><h3 id="phase-1-foundation-60-minutes" tabindex="-1">Phase 1: Foundation (60 minutes) <a class="header-anchor" href="#phase-1-foundation-60-minutes" aria-label="Permalink to &quot;Phase 1: Foundation (60 minutes)&quot;">​</a></h3><h4 id="_1-welcome-ground-rules-15-min" tabindex="-1">1. Welcome &amp; Ground Rules (15 min) <a class="header-anchor" href="#_1-welcome-ground-rules-15-min" aria-label="Permalink to &quot;1. Welcome &amp; Ground Rules (15 min)&quot;">​</a></h4><p><strong>The Social Contract:</strong></p><div class="tip custom-block"><p class="custom-block-title">The Container - Essential Ground Rules</p><p>Before any sharing begins, the group MUST agree to:</p><ol><li><strong>Confidentiality</strong> - What&#39;s said here, stays here</li><li><strong>The Vegas Rule</strong> - Lessons leave the room, stories stay</li><li><strong>No Fixing</strong> - Witness and understand, don&#39;t try to solve</li><li><strong>Right to Pass</strong> - Vulnerability cannot be coerced</li><li><strong>Respect the Process</strong> - Trust the discomfort</li></ol></div><p><strong>Your Script:</strong></p><blockquote><p>&quot;Welcome. This space is different from the piste. Here, we explore what happens <em>inside</em> when you&#39;re standing over that shot. Everything shared here is confidential. The lessons you learn can leave, but the personal stories stay. You&#39;re not here to fix each other - just to understand. And you can always pass. Can everyone agree to this?&quot;</p></blockquote><h4 id="_2-activity-the-check-in-matrix-20-min" tabindex="-1">2. Activity: The Check-In Matrix (20 min) <a class="header-anchor" href="#_2-activity-the-check-in-matrix-20-min" aria-label="Permalink to &quot;2. Activity: The Check-In Matrix (20 min)&quot;">​</a></h4><p><strong>Goal:</strong> Normalize admitting to fatigue or stress</p><p><strong>Materials:</strong> Whiteboard or flip chart, sticky notes</p><p><strong>Procedure:</strong></p><ol><li>Draw 2x2 matrix: High/Low Energy (vertical), Positive/Negative (horizontal)</li><li>Each player writes their name on sticky note</li><li>Place note in their current quadrant</li><li>Discuss: &quot;We have three people in &#39;Low Energy/Negative&#39;. How does this affect our session today?&quot;</li></ol>',12)),(a(),s(u,null,{default:h(()=>[r(b,{id:"mermaid-719",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BCheck-In%20Matrix%5D%20--%3E%20B%5BHigh%20Energy%20%2B%20Positive%5D%0A%20%20%20%20A%20--%3E%20C%5BHigh%20Energy%20%2B%20Negative%5D%0A%20%20%20%20A%20--%3E%20D%5BLow%20Energy%20%2B%20Positive%5D%0A%20%20%20%20A%20--%3E%20E%5BLow%20Energy%20%2B%20Negative%5D%0A%0A%20%20%20%20B%20--%3E%20F%5BAcknowledge%20All%20States%5D%0A%20%20%20%20C%20--%3E%20F%0A%20%20%20%20D%20--%3E%20F%0A%20%20%20%20E%20--%3E%20F%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:h(()=>[...c[2]||(c[2]=[l(" Loading... ",-1)])]),_:1})),c[9]||(c[9]=n('<p><strong>Facilitation Tips:</strong></p><ul><li>Don&#39;t judge any quadrant as &quot;bad&quot;</li><li>Ask: &quot;What does your body need right now?&quot;</li><li>Notice patterns: &quot;Three of you are in the same space - what&#39;s that about?&quot;</li></ul><h4 id="_3-activity-the-iceberg-of-petanque-25-min" tabindex="-1">3. Activity: The Iceberg of Pétanque (25 min) <a class="header-anchor" href="#_3-activity-the-iceberg-of-petanque-25-min" aria-label="Permalink to &quot;3. Activity: The Iceberg of Pétanque (25 min)&quot;">​</a></h4><p><strong>Goal:</strong> Visualize hidden inner thoughts</p><p><strong>Materials:</strong> Large paper, markers</p><p><strong>Procedure:</strong></p><ol><li>Draw iceberg on paper</li><li><strong>Above water:</strong> Write &quot;Technique, The Throw, The Result&quot;</li><li><strong>Below water:</strong> Ask: &quot;What&#39;s happening in your mind that nobody sees?&quot;</li></ol><p><strong>Prompts:</strong></p><ul><li>&quot;What are you afraid of when you step up to shoot?&quot;</li><li>&quot;What judgment are you worried about?&quot;</li><li>&quot;What does your inner voice say when you miss?&quot;</li></ul><p><strong>The Insight Question:</strong></p><blockquote><p>&quot;What happens to your throwing arm when the &#39;underwater&#39; stuff gets too heavy?&quot;</p></blockquote><p>This links mental load to physical tension (the bibber/yips).</p><details class="details custom-block"><summary>Common &quot;Below Water&quot; Responses</summary><ul><li>Fear of letting team down</li><li>Worry about looking stupid</li><li>Doubt about ability</li><li>Comparison to others</li><li>Pressure to prove worth</li><li>Fear of judgment from coach/teammates</li><li>Impostor syndrome</li></ul></details>',13)),r(q),c[10]||(c[10]=n('<h3 id="phase-2-deep-work-90-minutes" tabindex="-1">Phase 2: Deep Work (90 minutes) <a class="header-anchor" href="#phase-2-deep-work-90-minutes" aria-label="Permalink to &quot;Phase 2: Deep Work (90 minutes)&quot;">​</a></h3><h4 id="_4-activity-the-user-manual-30-min" tabindex="-1">4. Activity: The User Manual (30 min) <a class="header-anchor" href="#_4-activity-the-user-manual-30-min" aria-label="Permalink to &quot;4. Activity: The User Manual (30 min)&quot;">​</a></h4><p><strong>Goal:</strong> Operationalize empathy - help teammates understand each other</p><p><strong>Materials:</strong> Worksheets (one per player)</p><p><strong>The User Manual Template:</strong></p><table tabindex="0"><thead><tr><th>Section</th><th>Prompt</th><th>Example</th></tr></thead><tbody><tr><td><strong>My Stress Signature</strong></td><td>&quot;When I am anxious, I...&quot;</td><td>&quot;...go completely quiet&quot;</td></tr><tr><td><strong>How to Handle Me</strong></td><td>&quot;When I miss a crucial shot, I need...&quot;</td><td>&quot;...silence, not encouragement&quot;</td></tr><tr><td><strong>My Inner Thought</strong></td><td>&quot;The lie I tell myself is...&quot;</td><td>&quot;...that I&#39;m not good enough&quot;</td></tr><tr><td><strong>My Trigger</strong></td><td>&quot;I get defensive when...&quot;</td><td>&quot;...someone questions my shot choice&quot;</td></tr></tbody></table><p><strong>Procedure:</strong></p><ol><li>Give players 10 minutes to complete in silence</li><li>Go around circle - each person shares ONE section</li><li>Others can ask clarifying questions (not advice!)</li><li>Coordinator validates each share</li></ol><p><strong>Facilitation Script:</strong></p><blockquote><p>&quot;This is your operating manual. When your teammate knows you go quiet when anxious, they won&#39;t take it personally. When they know you need silence after a miss, they won&#39;t try to &#39;fix&#39; you. This is how we build team intelligence.&quot;</p></blockquote><h4 id="_5-connecting-website-content-to-inner-thought-30-min" tabindex="-1">5. Connecting Website Content to Inner Thought (30 min) <a class="header-anchor" href="#_5-connecting-website-content-to-inner-thought-30-min" aria-label="Permalink to &quot;5. Connecting Website Content to Inner Thought (30 min)&quot;">​</a></h4><p><strong>Goal:</strong> Bridge technical content to psychological experience</p><p>Choose 2-3 sections from the Academy website and explore the inner game:</p><p><strong>Example 1: Technique - The Grip and Release</strong></p><p><strong>The Trust Question:</strong></p><blockquote><p>&quot;When you&#39;re at 12-12 in a tournament, does your hand <em>feel</em> like the technique description? Is it the muscles changing or the thought &#39;Don&#39;t drop it&#39; that changes your grip?&quot;</p></blockquote><p><strong>The Micro-Tremor:</strong></p><blockquote><p>&quot;Who here feels the &#39;micro-tremor&#39; of anxiety? What inner thought triggers that?&quot;</p></blockquote><p><strong>Example 2: Tactics - Pointing vs. Shooting</strong></p><p><strong>Risk Profile:</strong></p><blockquote><p>&quot;When the guide says &#39;Shoot to win,&#39; is your reaction excitement or dread? What does that tell you about your relationship with risk?&quot;</p></blockquote><p><strong>The Impostor:</strong></p><blockquote><p>&quot;Do you ever point when you <em>know</em> you should shoot, just to avoid the embarrassment of missing? What&#39;s the cost of that safety?&quot;</p></blockquote><p><strong>Example 3: Nutrition - Competition Day</strong></p><p><strong>The Comfort Food Trap:</strong></p><blockquote><p>&quot;Do you eat what your body needs or what your anxiety wants? How do you know the difference?&quot;</p></blockquote><div class="tip custom-block"><p class="custom-block-title">Facilitation Technique</p><p>Don&#39;t lecture about the content. Ask questions that connect the technical information to their lived experience. The insight comes from THEM, not you.</p></div><h4 id="_6-activity-fear-in-a-hat-30-min" tabindex="-1">6. Activity: Fear in a Hat (30 min) <a class="header-anchor" href="#_6-activity-fear-in-a-hat-30-min" aria-label="Permalink to &quot;6. Activity: Fear in a Hat (30 min)&quot;">​</a></h4><p><strong>Goal:</strong> Break the isolation loop - show that peers share deep insecurities</p><p><strong>Materials:</strong> Paper, pen, hat/bag</p><p><strong>Procedure:</strong></p><ol><li>Everyone writes a deep career/team fear anonymously</li><li>Fold papers and mix in hat</li><li>Each player draws a note (not their own)</li><li>Read it aloud</li><li>Validate it: &quot;I can understand why someone would feel this way because...&quot;</li></ol><p><strong>Example Fears:</strong></p><ul><li>&quot;I&#39;m afraid I&#39;ve peaked and will never improve&quot;</li><li>&quot;I worry my teammates think I&#39;m overrated&quot;</li><li>&quot;I fear I&#39;ll choke in the big moment&quot;</li><li>&quot;I&#39;m scared of being replaced by younger players&quot;</li></ul><p><strong>The Power:</strong> When players hear their secret fear read aloud and validated by peers, the shame dissolves. They realize: &quot;I&#39;m not alone. This is normal.&quot;</p><p><strong>Coordinator&#39;s Role:</strong></p><ul><li>Validate EVERY fear as legitimate</li><li>Don&#39;t minimize: &quot;That&#39;s not true!&quot; invalidates the feeling</li><li>Ask: &quot;How many of you have felt something similar?&quot;</li></ul>',37)),(a(),s(u,null,{default:h(()=>[r(b,{id:"mermaid-1100",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BFear%20in%20a%20Hat%5D%20--%3E%20B%5BAnonymous%20Sharing%5D%0A%20%20%20%20B%20--%3E%20C%5BPeer%20Validation%5D%0A%20%20%20%20C%20--%3E%20D%5BShame%20Dissolves%5D%0A%20%20%20%20D%20--%3E%20E%5BIsolation%20Breaks%5D%0A%20%20%20%20E%20--%3E%20F%5BPsychological%20Safety%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffe4e1%0A%20%20%20%20style%20F%20fill%3A%23e8f5e9%0A"})]),fallback:h(()=>[...c[3]||(c[3]=[l(" Loading... ",-1)])]),_:1})),c[11]||(c[11]=n('<h3 id="phase-3-integration-45-minutes" tabindex="-1">Phase 3: Integration (45 minutes) <a class="header-anchor" href="#phase-3-integration-45-minutes" aria-label="Permalink to &quot;Phase 3: Integration (45 minutes)&quot;">​</a></h3><h4 id="_7-activity-reframing-the-inner-critic-25-min" tabindex="-1">7. Activity: Reframing the Inner Critic (25 min) <a class="header-anchor" href="#_7-activity-reframing-the-inner-critic-25-min" aria-label="Permalink to &quot;7. Activity: Reframing the Inner Critic (25 min)&quot;">​</a></h4><p><strong>Goal:</strong> Cognitive restructuring - change the internal dialogue</p><p><strong>Materials:</strong> Worksheet</p><p><strong>Procedure:</strong></p><p><strong>Step 1: Identify the Critic (10 min)</strong></p><blockquote><p>&quot;Write down the EXACT phrase your inner critic says after a miss. Not the polite version - the brutal one.&quot;</p></blockquote><p>Examples:</p><ul><li>&quot;You always choke&quot;</li><li>&quot;Everyone&#39;s watching you fail&quot;</li><li>&quot;You&#39;re embarrassing yourself&quot;</li><li>&quot;You don&#39;t belong here&quot;</li></ul><p><strong>Step 2: Reframe as Inner Coach (10 min)</strong></p><blockquote><p>&quot;Now rewrite that as your Inner Coach - firm but supportive.&quot;</p></blockquote><p>Examples:</p><ul><li>Critic: &quot;You always choke&quot; → Coach: &quot;Reset and breathe. Next shot.&quot;</li><li>Critic: &quot;Everyone&#39;s watching you fail&quot; → Coach: &quot;Focus on the target, not the crowd&quot;</li><li>Critic: &quot;You&#39;re embarrassing yourself&quot; → Coach: &quot;One shot at a time. You&#39;ve done this before.&quot;</li></ul><p><strong>Step 3: Partner Practice (5 min)</strong></p><blockquote><p>&quot;Share your Coach phrase with a partner. They&#39;ll remind you of it when they see the Critic emerge.&quot;</p></blockquote><h4 id="_8-bridging-to-the-piste-20-min" tabindex="-1">8. Bridging to the Piste (20 min) <a class="header-anchor" href="#_8-bridging-to-the-piste-20-min" aria-label="Permalink to &quot;8. Bridging to the Piste (20 min)&quot;">​</a></h4><p><strong>Goal:</strong> Create actionable protocols for competition</p><p><strong>Discussion Questions:</strong></p><ol><li>&quot;What&#39;s ONE thing from today you&#39;ll use in your next competition?&quot;</li><li>&quot;How will your teammates know you need support?&quot;</li><li>&quot;What&#39;s your signal for &#39;I need a mental reset&#39;?&quot;</li></ol><p><strong>Create Team Protocols:</strong></p><table tabindex="0"><thead><tr><th>Situation</th><th>Protocol</th><th>Example</th></tr></thead><tbody><tr><td><strong>After a miss</strong></td><td>Check User Manual</td><td>&quot;Marc needs silence, Lisa needs a fist bump&quot;</td></tr><tr><td><strong>Feeling pressure</strong></td><td>Use Coach phrase</td><td>&quot;Reset and breathe&quot;</td></tr><tr><td><strong>Team tension</strong></td><td>Call timeout</td><td>&quot;Let&#39;s take 2 minutes&quot;</td></tr><tr><td><strong>Inner critic loud</strong></td><td>Physical reset</td><td>Touch boules, deep breath</td></tr></tbody></table><h3 id="phase-4-closing-15-minutes" tabindex="-1">Phase 4: Closing (15 minutes) <a class="header-anchor" href="#phase-4-closing-15-minutes" aria-label="Permalink to &quot;Phase 4: Closing (15 minutes)&quot;">​</a></h3><h4 id="_9-the-check-out-10-min" tabindex="-1">9. The Check-Out (10 min) <a class="header-anchor" href="#_9-the-check-out-10-min" aria-label="Permalink to &quot;9. The Check-Out (10 min)&quot;">​</a></h4><p><strong>Procedure:</strong> Go around circle, each person shares:</p><ol><li><strong>One thing you&#39;re taking:</strong> &quot;What insight or tool are you leaving with?&quot;</li><li><strong>One thing you&#39;re leaving behind:</strong> &quot;What are you letting go of?&quot;</li></ol><p><strong>Coordinator&#39;s Role:</strong></p><ul><li>Thank each person for their contribution</li><li>Validate the work done</li><li>Remind of confidentiality</li></ul><h4 id="_10-follow-up-protocol-5-min" tabindex="-1">10. Follow-Up Protocol (5 min) <a class="header-anchor" href="#_10-follow-up-protocol-5-min" aria-label="Permalink to &quot;10. Follow-Up Protocol (5 min)&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">Critical: Prevent Vulnerability Hangover</p><p>Deep work causes a &quot;vulnerability hangover&quot; - regret or shame about sharing.</p><p><strong>Your 24-Hour Protocol:</strong></p><ul><li>Text anyone who shared heavily within 24 hours</li><li>Message: &quot;Thank you for your courage yesterday. What you shared helped everyone.&quot;</li><li>Check in: &quot;How are you feeling about the session?&quot;</li></ul></div><p><strong>Closing Script:</strong></p><blockquote><p>&quot;What happened here today took courage. You showed up, you opened up, you trusted the process. That same courage is what you&#39;ll bring to the piste. Remember: the lessons leave this room, but the stories stay. Thank you.&quot;</p></blockquote>',31)),r(q),c[12]||(c[12]=n('<h2 id="handling-resistance" tabindex="-1">Handling Resistance <a class="header-anchor" href="#handling-resistance" aria-label="Permalink to &quot;Handling Resistance&quot;">​</a></h2><h3 id="the-too-cool-athlete" tabindex="-1">The &quot;Too Cool&quot; Athlete <a class="header-anchor" href="#the-too-cool-athlete" aria-label="Permalink to &quot;The &quot;Too Cool&quot; Athlete&quot;">​</a></h3><p><strong>Scenario:</strong> A player rolls their eyes at a vulnerability exercise</p><p><strong>Strategy:</strong> Verbal Aikido (Align and Pivot)</p><p><strong>Script:</strong></p><blockquote><p>&quot;I see that reaction, [Name]. Honestly, I get it. Talking about feelings feels soft. But the piste is uncomfortable. If we can&#39;t handle the discomfort of this room, we aren&#39;t training our tolerance for the discomfort of the game. Can you trust me for 20 minutes?&quot;</p></blockquote><h3 id="the-silent-participant" tabindex="-1">The Silent Participant <a class="header-anchor" href="#the-silent-participant" aria-label="Permalink to &quot;The Silent Participant&quot;">​</a></h3><p><strong>Scenario:</strong> Someone hasn&#39;t spoken in 45 minutes</p><p><strong>Strategy:</strong> Create low-stakes entry point</p><p><strong>Script:</strong></p><blockquote><p>&quot;[Name], I notice you&#39;re taking it all in. What&#39;s one thing that&#39;s resonating with you so far? Even just a word.&quot;</p></blockquote><h3 id="the-over-sharer" tabindex="-1">The Over-Sharer <a class="header-anchor" href="#the-over-sharer" aria-label="Permalink to &quot;The Over-Sharer&quot;">​</a></h3><p><strong>Scenario:</strong> Someone dominates with long stories</p><p><strong>Strategy:</strong> Gentle redirect</p><p><strong>Script:</strong></p><blockquote><p>&quot;Thank you for that, [Name]. I want to make sure everyone has space. Let&#39;s hear from someone who hasn&#39;t shared yet.&quot;</p></blockquote><h3 id="the-fixer" tabindex="-1">The Fixer <a class="header-anchor" href="#the-fixer" aria-label="Permalink to &quot;The Fixer&quot;">​</a></h3><p><strong>Scenario:</strong> Someone tries to solve others&#39; problems</p><p><strong>Strategy:</strong> Reinforce ground rules</p><p><strong>Script:</strong></p><blockquote><p>&quot;I appreciate you wanting to help, but remember our rule: witness and understand, don&#39;t fix. [Original speaker], what do you need right now?&quot;</p></blockquote><h2 id="materials-checklist" tabindex="-1">Materials Checklist <a class="header-anchor" href="#materials-checklist" aria-label="Permalink to &quot;Materials Checklist&quot;">​</a></h2><details class="details custom-block"><summary>Workshop Materials</summary><p><strong>Physical Setup:</strong></p><ul><li>[ ] Chairs (6-8, no tables)</li><li>[ ] Boules and cochonnet for center</li><li>[ ] Flip chart or whiteboard</li><li>[ ] Markers</li></ul><p><strong>Activities:</strong></p><ul><li>[ ] Sticky notes (Check-In Matrix)</li><li>[ ] Large paper (Iceberg activity)</li><li>[ ] User Manual worksheets</li><li>[ ] Paper and pens (Fear in a Hat)</li><li>[ ] Inner Critic/Coach worksheets</li></ul><p><strong>Logistics:</strong></p><ul><li>[ ] Water for participants</li><li>[ ] Tissues (emotional work!)</li><li>[ ] Timer (keep on schedule)</li><li>[ ] Participant contact list (for follow-up)</li></ul></details><h2 id="coordinator-self-care" tabindex="-1">Coordinator Self-Care <a class="header-anchor" href="#coordinator-self-care" aria-label="Permalink to &quot;Coordinator Self-Care&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">You Need Support Too</p><p>Holding space for vulnerability is emotionally demanding.</p><p><strong>After the workshop:</strong></p><ul><li>Debrief with a peer or supervisor</li><li>Journal about what came up for you</li><li>Take a walk or physical break</li><li>Don&#39;t carry their stories home</li></ul></div><h2 id="measuring-impact" tabindex="-1">Measuring Impact <a class="header-anchor" href="#measuring-impact" aria-label="Permalink to &quot;Measuring Impact&quot;">​</a></h2><h3 id="immediate-feedback" tabindex="-1">Immediate Feedback <a class="header-anchor" href="#immediate-feedback" aria-label="Permalink to &quot;Immediate Feedback&quot;">​</a></h3><p>At the end, ask:</p><ol><li>&quot;On a scale of 1-10, how safe did you feel sharing today?&quot;</li><li>&quot;What&#39;s one thing that would make the next session better?&quot;</li></ol><h3 id="long-term-tracking" tabindex="-1">Long-Term Tracking <a class="header-anchor" href="#long-term-tracking" aria-label="Permalink to &quot;Long-Term Tracking&quot;">​</a></h3><p>Follow up after 2-4 weeks:</p><ul><li>&quot;Have you used any tools from the workshop?&quot;</li><li>&quot;How has your relationship with your inner critic changed?&quot;</li><li>&quot;What&#39;s different in your competition mindset?&quot;</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Building on This Foundation</p><p>This workshop is Phase 1. Consider:</p><ul><li><strong>Follow-up sessions</strong> (online or in-person)</li><li><strong>On-piste integration</strong> (see Training Session guide)</li><li><strong>Team protocols</strong> (implement User Manuals in competition)</li><li><strong>Individual check-ins</strong> (for players who need more support)</li></ul></div>',34)),r(f)])}]]);export{c as __pageData,d as default};
